body.script:
(async function () {
  const repo = "shajhgsjhgajshgkjajasfhlkahlalfd/shajhgsjhgajshgkjajasfhlkahlalfd";
  const status = document.getElementById('status');
  const frame = document.getElementById('site');
  async function get(url, options) {
    const response = await fetch(url, {...options, signal: AbortSignal.timeout(25000)});
    if (!response.ok) throw new Error('HTTP ' + response.status);
    return response;
  }
  try {
    const ref = await (await get('https://api.github.com/repos/' + repo + '/commits/main?_fresh=' + Date.now(), {
      cache: 'no-store', headers: {Accept: 'application/vnd.github+json'}
    })).json();
    if (!/^[a-f0-9]{40}$/i.test(ref.sha || '')) throw new Error('Invalid commit response');
    const base = 'https://cdn.jsdelivr.net/gh/' + repo + '@' + ref.sha + '/';
    const html = await (await get(base + 'index.html', {cache: 'no-store'})).text();
    const parsed = new DOMParser().parseFromString(html, 'text/html');
    parsed.querySelectorAll('base').forEach(node => node.remove());
    const baseTag = parsed.createElement('base');
    baseTag.href = base;
    parsed.head.prepend(baseTag);
    let observer;
    function connect() {
      try {
        const doc = frame.contentDocument;
        if (!doc || !doc.head) return;
        if (observer) observer.disconnect();
        function sync() {
          document.title = doc.title || 'Classroom-x-zone';
          const source = doc.querySelector('#favicon') || doc.querySelector('link[rel~="icon"]');
          const href = source ? new URL(source.getAttribute('href') || '', doc.baseURI).href : '';
          const target = document.getElementById('outer-icon');
          if (href && /^(https?:|data:|blob:)/i.test(href) && target.getAttribute('href') !== href) {
            target.href = href;
            if (source.type) target.type = source.type;
            else target.removeAttribute('type');
          }
        }
        observer = new MutationObserver(sync);
        observer.observe(doc.head, {subtree: true, childList: true, characterData: true, attributes: true});
        sync();
      } catch (error) { console.warn('Tab sync:', error); }
    }
    frame.addEventListener('load', connect);
    const doc = frame.contentDocument;
    doc.open();
    doc.write('\n' + parsed.documentElement.outerHTML);
    doc.close();
    connect();
    status.hidden = true;
    frame.hidden = false;
  } catch (error) {
    console.error('Loader error:', error);
    status.textContent = 'Unable to load the latest site: ' + error.message + '. Check your connection or GitHub API limits, then reload. No older copy was loaded.';
  }
})();
